import {afterAll,afterEach,beforeAll,beforeEach,describe,expect,it} from 'bun:test';
import React from 'react';
import {cleanup,fireEvent,render,waitFor} from '@testing-library/react';
import mermaid from 'mermaid';
import {existsSync,readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import postcss from 'postcss';
import inventory from '../../docs/migration-inventory/beautiful-testing-guide.json';
import {source,signature,normalize} from './source';
let originalRender:typeof mermaid.render;
const charts:string[]=[];
beforeAll(()=>{originalRender=mermaid.render;mermaid.render=async (_id,chart)=>{charts.push(chart);return {svg:'<svg></svg>',diagramType:'flowchart'};};});
afterAll(()=>{mermaid.render=originalRender;});
beforeEach(()=>{charts.length=0;});
afterEach(cleanup);
async function page(){const {default:Page}=await import('../../app/beautiful-testing-guide/page');const result=render(<Page/>);await waitFor(()=>expect(result.container.querySelectorAll('.diagram-frame svg')).toHaveLength(result.container.querySelectorAll('.diagram-frame').length));return result;}
function diagramFrames(root:Element){return [...root.querySelectorAll('.mermaid-wrapper')].filter(node=>!node.parentElement?.closest('.mermaid-wrapper'));}
function section(container:HTMLElement,id:string){const node=container.querySelector('#'+id);expect(node,id).not.toBeNull();return node!;}
describe('foundation',()=>{
 it('freezes every source inventory in exact order',()=>{
 for(const selector of ["h1,h2,h3,h4",".sidebar nav a",".mermaid-wrapper","table","pre:not(.mermaid) code",".callout",".section-refs a,.ref-list li",".checklist li"]){
 const actual=[...source.querySelectorAll(selector)].map(node=>({tag:node.tagName.toLowerCase(),id:node.id,class:node.getAttribute('class')??'',href:node.getAttribute('href')??'',text:normalize(node.textContent??'')}));
 expect(JSON.stringify(actual)).toBe(JSON.stringify(inventory[selector as keyof typeof inventory]));
 }
 });
 it('preserves hero and footer structure and content',async()=>{const {container}=await page();for(const selector of ['header.hero','footer.footer'])expect(signature(container.querySelector(selector)!)).toEqual(signature(source.querySelector(selector)!));});
});
it("foundation CSS 0: :root ",async()=>{await page();const css=postcss.parse(readFileSync('app/beautiful-testing-guide/beautiful-testing-guide.css','utf8'));const expected=inventory.css[0]!;const selector=expected.selector.split(',').map(s=>[':root','html','body'].includes(s.trim())?'.bt-page':'.bt-page '+s.trim()).join(', ');let found=false;css.walkRules(rule=>{if(rule.selector.split(',').map(s=>s.trim()).join(', ')!==selector||(rule.parent?.type==='atrule'?(rule.parent as postcss.AtRule).params:'')!==expected.media)return;const declarations=rule.nodes.filter(n=>n.type==='decl').map(n=>[(n as postcss.Declaration).prop,(n as postcss.Declaration).value.replace(/\s+/g,' ').trim()]);if(JSON.stringify(declarations)===JSON.stringify(expected.declarations))found=true;});expect(found).toBe(true);});
